    const char *ref_start, *msg_start;
    size_t ref_len, msg_len;

    if (line == NULL || len < 4) {
        return -1;
    }

    if (memcmp(line, "pkt-", 4) != 0) {
        return -1;
    }

    pkt = (git_pkt_ng *)malloc(sizeof(git_pkt_ng));
    if (pkt == NULL) {
        return -1;
    }

