        free(pkt);
        return -1;
    }

    msg_start = ref_start + ref_len + 1;
    msg_len = len - (msg_start - line);

    pkt->ref = (char *)malloc(ref_len + 1);
    if (pkt->ref == NULL) {
        free(pkt);
        return -1;
    }

